import 'react-native-get-random-values';
import { createElement } from 'react';
import { registerRootComponent } from 'expo';
import { WdkAppProvider } from '@tetherto/wdk-react-native-core';
// Generated by wdk-worklet-bundler on install (a string module).
import wdkBundle from './.wdk-bundle/wdk-worklet.bundle.js';
import App from './App';
import sponsor from './sponsor.local.json'; // written by npm run sync from .env (gitignored: it carries the Candide key)

// An EIP-7702 account on Sepolia: the phone sends its own buys as UserOperations through Candide's bundler, and its
// paymaster pays the gas under Nico's own policy (the public one stopped qualifying ops on 20 Nov 2026).
const wdkConfigs = { networks: { ethereum: { blockchain: 'ethereum',
  config: { chainId: 11155111, provider: 'https://ethereum-sepolia-rpc.publicnode.com',
    bundlerUrl: (sponsor as { bundlerUrl?: string }).bundlerUrl ?? 'https://api.candide.dev/public/v3/11155111',
    delegationAddress: '0xe6Cae83BdE06E4c305530e199D7217f42808555B', isSponsored: true,
    ...((sponsor as { sponsorshipPolicyId?: string }).sponsorshipPolicyId ? { sponsorshipPolicyId: (sponsor as { sponsorshipPolicyId: string }).sponsorshipPolicyId } : {}) } } } };

registerRootComponent(() => createElement(WdkAppProvider, { wdkConfigs, bundle: { bundle: wdkBundle as string }, children: createElement(App) }));
